let gateway={url:'http://127.0.0.1:4320',bindings:{}},gatewayToken='',remoteAgents=[],gatewayStatus='Chưa kiểm tra',gatewayBusy=false,realResults=[];
try{const g=JSON.parse(localStorage.getItem('tram-gateway-v1'));if(g&&typeof g.url==='string'&&g.bindings&&typeof g.bindings==='object'&&!Array.isArray(g.bindings))gateway=g;const results=JSON.parse(localStorage.getItem('tram-real-results-v1'));if(Array.isArray(results))realResults=results.filter(r=>r&&typeof r.projectId==='string'&&typeof r.role==='string'&&typeof r.output==='string'&&typeof r.time==='string').slice(-100)}catch{}
const gatewayNav=document.createElement('button');gatewayNav.textContent='⚡';gatewayNav.title='Kết nối AI / Agent';gatewayNav.setAttribute('aria-label','Kết nối AI / Agent');gatewayNav.dataset.panel='connections';gatewayNav.onclick=()=>openPanel('connections');$('.rail').insertBefore(gatewayNav,$('.rail-end'));
function saveGateway(){try{localStorage.setItem('tram-gateway-v1',JSON.stringify(gateway));localStorage.setItem('tram-real-results-v1',JSON.stringify(realResults.slice(-100)))}catch{}}
function gatewayURL(raw){const u=new URL(raw.trim());if(u.username||u.password||u.search||u.hash)throw Error('Địa chỉ cổng không được chứa thông tin đăng nhập, tham số hoặc mã bí mật.');if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1','[::1]'].includes(u.hostname)))throw Error('Dùng HTTPS hoặc địa chỉ loopback HTTP trên máy của bạn.');return u.href.replace(/\/$/,'')}
async function gatewayFetch(path,options={}){const base=gatewayURL(gateway.url);const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),path==='/tasks'?125000:10000);try{const res=await fetch(base+path,{...options,signal:controller.signal,credentials:'omit',headers:{'Content-Type':'application/json',...(gatewayToken?{Authorization:'Bearer '+gatewayToken}:{}),...options.headers}});const text=await res.text();if(text.length>300000)throw Error('Phản hồi cổng quá lớn.');let data;try{data=JSON.parse(text)}catch{throw Error('Cổng chưa trả JSON đúng hợp đồng.')}if(!res.ok)throw Error(typeof data.error==='string'?data.error:'Cổng trả lỗi '+res.status);return data;}catch(e){if(e.name==='AbortError')throw Error('Cổng phản hồi quá thời gian. Kiểm tra worker và nhật ký máy chủ.');if(e instanceof TypeError)throw Error('Không truy cập được cổng. Kiểm tra địa chỉ, HTTPS, CORS, token và quyền truy cập mạng cục bộ của trình duyệt.');throw e}finally{clearTimeout(timeout)}}
panelExtensions.connections=function(){panel('Kết nối AI / Agent',`<p class="notice">Cổng HTTP kết nối tới agent của bạn. Luồng văn phòng vẫn là mô phỏng; tác vụ gửi thật có nút riêng và kết quả riêng.</p><form id="gatewayForm"><label>Địa chỉ cổng agent<input id="gatewayAddress" type="url" value="${escapeHTML(gateway.url)}" required placeholder="https://agent.example.com"></label><label>Token truy cập cổng <small>(chỉ giữ trong phiên này)</small><input id="gatewayToken" type="password" autocomplete="off" placeholder="Token gateway, không phải khóa dịch vụ AI" value="${escapeHTML(gatewayToken)}"></label><button class="primary full" ${gatewayBusy?'disabled':''}>${gatewayBusy?'Đang kiểm tra…':'Lưu & kiểm tra kết nối'}</button></form><p class="muted" role="status">${escapeHTML(gatewayStatus)}</p><h3 class="section-label">GÁN AGENT CHO TỪNG PHI PHI</h3>${remoteAgents.length?`<p class="muted">Cổng cung cấp ${remoteAgents.length} agent. Nhiều vai trò có thể dùng chung một agent.</p><form id="bindingForm">${staff.map(a=>`<label>${a.id} · ${a.short}<select name="${a.id}"><option value="">Chưa gán</option>${remoteAgents.map(remote=>`<option value="${escapeHTML(remote.id)}" ${gateway.bindings[a.id]===remote.id?'selected':''}>${escapeHTML(remote.name)} · ${escapeHTML(remote.id)}</option>`).join('')}</select></label>`).join('')}<button class="primary full">Lưu phân vai</button></form><h3 class="section-label">GỬI MỘT TÁC VỤ THẬT</h3><form id="realTaskForm"><label>Phi Phi nhận việc<select name="role">${staff.map(a=>`<option value="${a.id}">${a.short} · ${a.role}</option>`).join('')}</select></label><label>Yêu cầu gửi tới agent<textarea name="task" required maxlength="12000" placeholder="VD: Phân tích ý tưởng và soạn đặc tả MVP..."></textarea></label><label class="checkbox-label"><input name="includeKnowledge" type="checkbox"> Gửi kèm tri thức của dự án ${escapeHTML(project().name)}</label><p class="muted">Nội dung nhập tại đây được gửi tới ${escapeHTML(gateway.url)}. Tác vụ có thể dùng hạn mức của dịch vụ bạn kết nối. Chưa có công cụ chạy mã trong giao diện này.</p><button class="primary full" ${gatewayBusy?'disabled':''}>${gatewayBusy?'Đang chờ agent…':'Gửi tác vụ tới agent'}</button></form>`:'<div class="empty">Kiểm tra cổng để tải danh sách agent.<br>Chưa gọi dịch vụ AI.</div>'}<h3 class="section-label">KẾT QUẢ TỪ AGENT THẬT</h3>${realResults.filter(r=>r.projectId===project().id).slice().reverse().map(r=>`<article class="card"><small>${escapeHTML(r.role)} · ${prettyTime(r.time)} · NGUỒN: CỔNG AGENT</small><p>${escapeHTML(r.output)}</p><small>Đầu ra cần kiểm tra trước khi sử dụng.</small></article>`).join('')||'<p class="muted">Chưa có kết quả thật cho dự án này.</p>'}<details class="card"><summary>Hợp đồng cổng HTTP</summary><p class="body-copy">GET /health → {status, ready}\nGET /agents → {agents: [{id, name}]}\nPOST /tasks → {agentId, roleId, projectId, task, context}\nPhản hồi → {status: "completed", output: "văn bản"}\n\nMáy chủ giữ khóa model và quyền công cụ. Browser chỉ giữ token truy cập cổng trong phiên. POST /tasks chạy đồng bộ, giới hạn 120 giây.</p></details>`);
$('#gatewayForm').onsubmit=async e=>{e.preventDefault();if(gatewayBusy)return;try{gateway.url=gatewayURL($('#gatewayAddress').value);gatewayToken=$('#gatewayToken').value.trim();saveGateway();gatewayBusy=true;gatewayStatus='Đang kiểm tra /health và /agents…';renderPanel('connections');const health=await gatewayFetch('/health');if(health.status!=='ok')throw Error('Cổng chưa sẵn sàng.');const data=await gatewayFetch('/agents');if(!Array.isArray(data.agents)||data.agents.length>100||!data.agents.every(a=>a&&typeof a.id==='string'&&a.id.length<=100&&typeof a.name==='string'&&a.name.length<=160))throw Error('Danh sách agent không đúng hợp đồng.');remoteAgents=data.agents;gatewayStatus=health.ready===false?'Đã tới cổng nhưng chưa cấu hình agent phía máy chủ.':`Đã kết nối. Tìm thấy ${remoteAgents.length} agent.`;}catch(err){remoteAgents=[];gatewayStatus=err.message;}finally{gatewayBusy=false;if(drawerView==='connections')renderPanel('connections')}};
if($('#bindingForm'))$('#bindingForm').onsubmit=e=>{e.preventDefault();gateway.bindings=Object.fromEntries(new FormData(e.target));saveGateway();toast('Đã lưu phân vai trên máy này.')};
if($('#realTaskForm'))$('#realTaskForm').onsubmit=async e=>{e.preventDefault();if(gatewayBusy)return;const f=Object.fromEntries(new FormData(e.target));const agentId=gateway.bindings[f.role];if(!agentId)return toast('Hãy gán agent cho vai trò này và lưu phân vai trước.');const task=f.task.trim();if(!task)return;const projectSnapshot={id:project().id,name:project().name,knowledge:f.includeKnowledge?project().knowledge:''};gatewayBusy=true;gatewayStatus='Đang gửi tác vụ thật. Không đóng trang khi chưa có kết quả.';renderPanel('connections');try{const result=await gatewayFetch('/tasks',{method:'POST',body:JSON.stringify({agentId,roleId:f.role,projectId:projectSnapshot.id,task,context:{projectName:projectSnapshot.name,knowledge:projectSnapshot.knowledge}})});if(result.status!=='completed'||typeof result.output!=='string'||result.output.length>200000)throw Error('Cổng chưa trả đầu ra completed dạng văn bản.');realResults.push({projectId:projectSnapshot.id,role:f.role,output:result.output,time:timestamp()});saveGateway();gatewayStatus='Đã nhận kết quả từ agent. Chưa xác nhận mã nguồn hoặc kiểm thử.';toast('Đã nhận đầu ra thật từ cổng agent.');}catch(err){gatewayStatus=err.message;}finally{gatewayBusy=false;if(drawerView==='connections')renderPanel('connections')}};
};
